import scala.language.dynamics

class DirDynamic(raw: Dir, m: Membrane) extends Dynamic:
  def selectDynamic(name: String): Any =
    if m.revoked then throw IllegalStateException("revoked")
    else m.wrap(raw.getClass.getMethod(name).invoke(raw))   // mediate the surface

  def applyDynamic(name: String)(args: Any*): Any =
    m.wrap(raw.getClass.getMethod(name, args.map(_.getClass)*).invoke(raw, args*))
